/* M04 — persistent reading settings and speech synchronized to visible text. */
(() => {
  const {$,on,save,load}=LB,defaults={size:'16',spacing:'comfortable',font:'serif',contrast:false,rate:'1'},settings={...defaults};
  const stored=load('reading',{});if(stored&&typeof stored==='object'){if(Number(stored.size)>=16&&Number(stored.size)<=24)settings.size=stored.size;if(['comfortable','wide'].includes(stored.spacing))settings.spacing=stored.spacing;if(['serif','sans'].includes(stored.font))settings.font=stored.font;if(['0.75','1','1.25'].includes(stored.rate))settings.rate=stored.rate;settings.contrast=stored.contrast===true;}
  let queue=[],index=0,active=false,paused=false,token=0,utterance;
  const supported='speechSynthesis' in window&&'SpeechSynthesisUtterance' in window;
  LB.modules.reading=()=>{
    $('#reading-module').innerHTML=`<section class="panel panel-pad reading-panel" data-module="04"><span class="module-label">M04 · READING & LISTENING</span><h2>Read your way</h2><div class="button-row speech-buttons"><button class="button small" id="global-pause" disabled>Pause</button><button class="button small" id="global-stop" disabled>Stop</button></div><p id="listen-status" class="status-text" role="status">${supported?'Tap ▶ on any card.':'Read-aloud is unavailable here. All text stays readable.'}</p><details class="reading-options" id="reading-options"><summary>Text size, spacing & voice</summary><div class="reading-settings"><div class="setting"><label for="text-size">Word size <output id="size-label">${settings.size}px</output></label><input type="range" min="16" max="24" step="2" id="text-size" value="${settings.size}"></div><div class="setting"><label for="reading-font">Letters</label><select id="reading-font"><option value="serif">Book letters</option><option value="sans">Simple letters</option></select></div><div class="setting"><label for="text-spacing">Line spacing</label><select id="text-spacing"><option value="comfortable">A little space</option><option value="wide">More space</option></select></div><div class="setting"><label for="read-speed">Voice speed</label><select id="read-speed"><option value="0.75">Slower</option><option value="1">Natural</option><option value="1.25">Quicker</option></select></div><label class="toggle-row">Clearer colors<input id="high-contrast" type="checkbox"></label></div><button class="text-button" id="reset-reading">Reset</button></details></section>`;
    sync();apply();$('#text-size').oninput=e=>{settings.size=e.target.value;apply();};
    $('#reading-font').onchange=e=>{settings.font=e.target.value;apply();};$('#text-spacing').onchange=e=>{settings.spacing=e.target.value;apply();};$('#high-contrast').onchange=e=>{settings.contrast=e.target.checked;apply();};$('#read-speed').onchange=e=>{settings.rate=e.target.value;stop('Tap Listen again for the new speed.');apply();};
    $('#reset-reading').onclick=()=>{Object.assign(settings,defaults);sync();apply();};$('#global-pause').onclick=pause;$('#global-stop').onclick=()=>stop();
    on('reading:toggle',()=>{if(active){pause();return;}start([{text:LB.card.title,node:$('#news-title')},...LB.card.sentences.map((text,i)=>({text,node:$(`[data-sentence="${i}"]`)}))]);});
    on('reading:evidence',({text,node})=>start([{text,node}]));on('reading:stop',()=>stop());on('draft:changed',()=>stop());on('view:changed',()=>stop());on('game:changed',()=>syncButtons());window.addEventListener('pagehide',()=>stop());syncButtons();
  };
  function sync(){$('#text-size').value=settings.size;$('#reading-font').value=settings.font;$('#text-spacing').value=settings.spacing;$('#high-contrast').checked=settings.contrast;$('#read-speed').value=settings.rate;}
  function apply(){const style=document.documentElement.style;style.setProperty('--reading-size',Number(settings.size)/16+'rem');style.setProperty('--reading-font',settings.font==='sans'?'"Trebuchet MS",Arial,sans-serif':'Georgia,serif');style.setProperty('--reading-leading',settings.spacing==='wide'?'2':'1.65');style.setProperty('--reading-tracking',settings.spacing==='wide'?'.04em':'0em');document.body.dataset.contrast=settings.contrast?'high':'normal';$('#size-label').value=settings.size+'px';save('reading',settings);}
  function status(text){if($('#listen-status'))$('#listen-status').textContent=text;if($('#speech-status'))$('#speech-status').textContent=text;}
  function syncButtons(){if($('#global-pause')){$('#global-pause').disabled=!active;$('#global-pause').textContent=paused?'Resume':'Pause';$('#global-stop').disabled=!active;}if($('#read-news')){$('#read-news').disabled=!supported;$('#read-news').textContent=active?(paused?'▶ Resume':'Ⅱ Pause'):'▶ Listen';$('#stop-read').disabled=!active;}}
  function clear(){document.querySelectorAll('.live-sentence,.live-word').forEach(n=>n.classList.remove('live-sentence','live-word'));}
  function stop(message='Tap ▶ on a card to listen.'){token++;active=false;paused=false;if(supported)speechSynthesis.cancel();clear();syncButtons();status(supported?message:'Read-aloud unavailable. You can read every card.');}
  function pause(){if(!active)return;if(paused)speechSynthesis.resume();else speechSynthesis.pause();paused=!paused;syncButtons();status(paused?'Paused.':'Reading aloud.');}
  function start(items){if(!supported){status('Read-aloud unavailable. You can read every card.');return;}LB.emit('voice:stop');stop();queue=items;index=0;active=true;syncButtons();speakNext(token);}
  function speakNext(run){
    if(run!==token)return;if(index>=queue.length){stop('Finished reading.');return;}clear();const {text,node}=queue[index];if(!node?.isConnected){stop();return;}
    const parts=text.match(/\S+\s*|\s+/g)||[text];let offset=0;node.replaceChildren(...parts.map(part=>{const s=document.createElement('span');s.textContent=part;s.dataset.offset=String(offset);offset+=part.length;return s;}));
    utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-US';utterance.rate=Number(settings.rate);
    utterance.onstart=()=>{if(run===token){node.classList.add('live-sentence');status('Reading aloud. Follow the highlight.');}};
    utterance.onboundary=e=>{if(run!==token||e.name!=='word')return;node.querySelectorAll('span').forEach(s=>s.classList.toggle('live-word',e.charIndex>=Number(s.dataset.offset)&&e.charIndex<Number(s.dataset.offset)+s.textContent.length));};
    utterance.onend=()=>{if(run===token){index++;speakNext(run);}};utterance.onerror=()=>{if(run===token)stop('Voice unavailable. You can read the card.');};
    try{speechSynthesis.speak(utterance);}catch{stop('Voice unavailable. You can read the card.');}
  }
})();
